			if (this.memoryManager) this.memoryManager.cleanup();
			this.isInitialized = false;
			if (this.wasmModule.HEAPU8) {
				if (this.wasmModule.HEAPU8.buffer) {
					if (typeof gc !== "undefined") gc();
				}
			}
