//#region core/NetworkLayer.ts
/**
* @internal
*/
var NetworkLayer = class {
	wsClient;
	dataController;
	/** Timestamp (ms) when WebSocket physically connected; null when disconnected. Used for session_duration_ms in error events. */
	connectionStartTime = null;
	isFallbackMode = false;
	/** @internal 降级原因，供 AvatarController 读取 */
	_fallbackReason = "";
	isConnecting = false;
	heartbeatTimer = null;
	visibilityChangeHandler = null;
	heartbeatFailureCount = 0;
	HEARTBEAT_INTERVAL = 12e4;
	constructor(dataController) {
		this.dataController = dataController;
		const config = AvatarSDK.getEnvironmentConfig();
		this.wsClient = new AnimationWebSocketClient({
			wsUrl: config.driveningressWsUrl,
			reconnectAttempts: 5,
			jwtToken: AvatarSDK.sessionToken || void 0,
			appId: AvatarSDK.appId || void 0,
			clientId: idManager.getClientId()
		});
		this.setupWebSocketListeners();
		this.startHeartbeatCheck();
	}
	/**
	* 连接服务
	*/
	async connect(characterId) {
		if (this.isConnecting) {
			logger.warn("[NetworkLayer] Connection already in progress, waiting for current connection to complete");
			throw new AvatarError("Connection already in progress", ErrorCode.connectionInProgress);
		}
		this.dataController.onConnectionState?.(ConnectionState.connecting);
		this.isFallbackMode = false;
		this._fallbackReason = "";
		this.setupWebSocketListeners();
		this.isConnecting = true;
		const CONNECTION_TIMEOUT_MS = 15e3;
		let timeoutId = null;
		const connectPromise = this.wsClient.connect(characterId);
		const timeoutPromise = new Promise((resolve) => {
			timeoutId = setTimeout(() => {
				if (!this.dataController.connected) {
					this.isFallbackMode = true;
					this._fallbackReason = "connection_timeout";
					logger.warn(`[NetworkLayer] WebSocket connection timeout (${CONNECTION_TIMEOUT_MS}ms) - entering fallback mode`);
					this.dataController.onConnectionState?.(ConnectionState.failed);
				}
				resolve();
			}, CONNECTION_TIMEOUT_MS);
		});
		try {
			await Promise.race([connectPromise, timeoutPromise]);
			if (timeoutId) clearTimeout(timeoutId);
		} catch (error) {
			if (timeoutId) clearTimeout(timeoutId);
			if (!this.isFallbackMode) {
				this.isFallbackMode = true;
				this._fallbackReason = "connection_failed";
				logger.warn("[NetworkLayer] WebSocket connection failed - entering fallback mode");
			}
			this.dataController.onConnectionState?.(ConnectionState.failed);
			throw error;
		} finally {
			this.isConnecting = false;
		}
	}
	/**
	* 检查是否可以发送音频数据（包括降级模式）
	* @internal
	*/
	canSend() {
		return this.isFallbackMode || this.dataController.connected;
	}
	/**
	* 发送音频数据到服务器
	* 注意：打断逻辑由 AvatarController.send() 统一处理，这里只负责网络通信。
	* conversationId 由 AvatarController 统一持有并传入（对齐 Android/iOS：网络层不持有 cid，只透传）。
	*/
	sendAudioData(conversationId, audioData, isLast) {
		if (audioData.byteLength === 0 && !isLast) logger.warn("[NetworkLayer] Warning: sending empty audio data (size=0, end=false)");
		if (this.isFallbackMode) {
			this.dataController.yieldKeyframes([], conversationId);
			return;
		}
		if (!this.wsClient.sendAudioData(conversationId, audioData, isLast)) {
			this.dataController.yieldKeyframes([], conversationId);
			return;
		}
	}
	/**
	* 断开连接
	*/
	disconnect() {
		this.isFallbackMode = false;
		this._fallbackReason = "";
		this.isConnecting = false;
		this.wsClient.removeAllListeners();
		this.wsClient.disconnect();
		this.stopHeartbeatCheck();
		idManager.clearConnectionId();
	}
	/**
	* 设置 WebSocket 事件监听器
	* Safety: Remove existing listeners before adding new ones to prevent duplicates
	*/
	setupWebSocketListeners() {
		this.wsClient.removeAllListeners();
		this.wsClient.on("sessionConfirmed", (connectionId) => {
			if (connectionId) logger.log(`[NetworkLayer] Session confirmed, connection_id: ${connectionId}, ready to send audio`);
			else logger.log("[NetworkLayer] Session confirmed, ready to send audio");
			if (!this.dataController.connected) {
				this.isFallbackMode = false;
				this._fallbackReason = "";
				this.dataController.setConnected(true);
				this.dataController.onConnectionState?.(ConnectionState.connected);
			}
		});
		this.wsClient.on("connected", () => {
			this.connectionStartTime = Date.now();
		});
		this.wsClient.on("disconnected", () => {
			this.dataController.setConnected(false);
			idManager.clearConnectionId();
			this.connectionStartTime = null;
			this.dataController.onConnectionState?.(ConnectionState.disconnected);
		});
		this.wsClient.on("reconnecting", () => {});
		this.wsClient.on("error", (error) => {
			const message = error instanceof Error ? error.message : String(error);
			logger.error("[NetworkLayer] WebSocket error:", message);
			this.dataController.onConnectionState?.(ConnectionState.failed);
			const avatarError = error instanceof AvatarError ? error : new AvatarError(message, ErrorCode.websocketError);
			this.dataController.onError?.(avatarError);
		});
		this.wsClient.on("message", (message) => {
			this.handleMessage(message);
		});
	}
	/**
	* 处理接收到的消息
	*/
	handleMessage(message) {
		try {
			switch (message.type) {
				case MessageType.MESSAGE_SERVER_RESPONSE_ANIMATION:
					this.handleAnimationMessage(message);
					break;
				case MessageType.MESSAGE_SERVER_ERROR:
					this.handleErrorMessage(message);
					break;
				default:
			}
		} catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			logger.error("[NetworkLayer] Failed to handle message:", message);
		}
	}
	/**
	* 处理动画消息
	*/
	handleAnimationMessage(message) {
		if (!message.serverResponseAnimation) {
			logger.error("[NetworkLayer] Invalid animation message");
			return;
		}
		const { reqId, animation, avatarId, end } = message.serverResponseAnimation;
		const conversationId = reqId;
		if (avatarId && avatarId !== this.dataController.getAvatarId()) {
			logger.error(`[NetworkLayer] Ignoring animation data for mismatched avatar - expected: ${this.dataController.getAvatarId()}, received: ${avatarId}`);
			logEvent("animation_avatar_id_mismatch", "error", {
				expected_avatar_id: this.dataController.getAvatarId(),
				received_avatar_id: avatarId,
				conversation_id: conversationId
			});
			this.dataController.onError?.(new AvatarError(`Animation data avatar_id mismatch - expected: ${this.dataController.getAvatarId()}, received: ${avatarId}`, ErrorCode.avatarIDUnrecognized));
			return;
		}
		const currentConversationId = this.dataController.getConversationId();
		if (!currentConversationId || conversationId !== currentConversationId) {
			logger.warn(`[NetworkLayer] Ignoring mismatched animation message - expected conversationId: ${currentConversationId}, received conversationId: ${conversationId}`);
			logEvent("keyframes_conversation_id_mismatch", "warning", {
				avatar_id: this.dataController.getAvatarId(),
				expected_conversation_id: currentConversationId,
				received_conversation_id: conversationId
			});
			return;
		}
		if (animation?.keyframes && animation.keyframes.length > 0) {
			const keyframes = animation.keyframes;
			try {
				this.dataController.yieldKeyframes(keyframes, conversationId, end);
			} catch (error) {
				const errorMessage = error instanceof Error ? error.message : String(error);
				logger.error(`[NetworkLayer] Failed to yield animation data: ${errorMessage}`);
				logEvent("yield_animation_failed", "error", {
					conversation_id: conversationId,
					description: errorMessage
				});
			}
		} else {
			logger.warn(`[NetworkLayer] Animation message has no animation data - conversationId: ${conversationId}`);
			logEvent("animation_empty_keyframes", "warning", {
				avatar_id: this.dataController.getAvatarId(),
				conversation_id: conversationId
			});
		}
	}
	/**
	* 处理错误消息
	*/
	handleErrorMessage(message) {
		if (!message.serverError) {
			logger.warn("[NetworkLayer] MESSAGE_SERVER_ERROR received but message.serverError is empty");
			return;
		}
		const conversationId = message.serverError.reqId || this.dataController.getConversationId() || "";
		logger.error(`[NetworkLayer] Server error: conversationId=${conversationId}, code=${message.serverError.code}, message=${message.serverError.message}`);
		logEvent("message_error", "error", {
			conversation_id: conversationId,
			description: message.serverError.message || `Server error: code=${message.serverError.code}`
		});
		const httpStatusCode = message.serverError.code;
		let sdkErrorCode;
		let errorMessage = message.serverError.message || "Server error occurred";
		const sessionDurationMs = this.connectionStartTime ? Date.now() - this.connectionStartTime : 0;
		if (httpStatusCode === 401) {
			sdkErrorCode = ErrorCode.sessionTokenExpired;
			logEvent("session_token_expired", "warning", {
				avatar_id: this.dataController.getAvatarId(),
				description: errorMessage,
				session_duration_ms: sessionDurationMs
			});
		} else if (httpStatusCode === 400) {
			sdkErrorCode = ErrorCode.sessionTokenInvalid;
			logEvent("session_token_invalid", "warning", {
				avatar_id: this.dataController.getAvatarId(),
				description: errorMessage,
				session_duration_ms: sessionDurationMs
			});
		} else if (httpStatusCode === 404) {
			sdkErrorCode = ErrorCode.avatarIDUnrecognized;
			errorMessage = errorMessage || "Avatar ID not recognized";
		} else sdkErrorCode = ErrorCode.serverError;
		this.dataController.onError?.(new AvatarError(errorMessage, sdkErrorCode));
		const currentConversationId = this.dataController.getConversationId();
		if (currentConversationId && conversationId === currentConversationId) {
			logger.warn("[NetworkLayer] Server error for current conversation - triggering fallback mode via empty animation data");
			this.dataController.yieldKeyframes([], conversationId);
		}
	}
	/**
	* Start driving service heartbeat check (check connection status every 2 minutes)
	* @internal
	*/
	startHeartbeatCheck() {
		this.stopHeartbeatCheck();
		this.heartbeatTimer = window.setInterval(() => {
			if (typeof document !== "undefined" && document.visibilityState === "visible") this.performHeartbeatCheck();
		}, this.HEARTBEAT_INTERVAL);
		this.setupVisibilityListener();
	}
	/**
	* Stop driving service heartbeat check
	* @internal
	*/
	stopHeartbeatCheck() {
		if (this.heartbeatTimer !== null) {
			clearInterval(this.heartbeatTimer);
			this.heartbeatTimer = null;
		}
		this.removeVisibilityListener();
		this.heartbeatFailureCount = 0;
	}
	/**
	* Perform heartbeat check: detect WebSocket connection status
	* If connection fails 3 times, report heartbeat_failed event
	* @internal
	*/
	performHeartbeatCheck() {
		try {
			if (this.wsClient.isConnected()) this.heartbeatFailureCount = 0;
			else {
				this.heartbeatFailureCount++;
				logger.warn(`[NetworkLayer] Driving service heartbeat failed (count: ${this.heartbeatFailureCount})`);
				if (this.heartbeatFailureCount >= 3) {
					logEvent("heartbeat_failed", "warning", { description: `Driving service heartbeat failed ${this.heartbeatFailureCount} times` });
					this.heartbeatFailureCount = 0;
				}
			}
		} catch (error) {
			this.heartbeatFailureCount++;
			logger.warn(`[NetworkLayer] Heartbeat check error (count: ${this.heartbeatFailureCount}):`, error instanceof Error ? error.message : String(error));
			if (this.heartbeatFailureCount >= 3) {
				logEvent("heartbeat_failed", "warning", { description: `Heartbeat check error: ${error instanceof Error ? error.message : String(error)}` });
				this.heartbeatFailureCount = 0;
			}
		}
	}
	/**
	* Setup page visibility listener (for immediately performing heartbeat check when page becomes visible)
	* @internal
	*/
	setupVisibilityListener() {
		if (typeof window === "undefined" || typeof document === "undefined") return;
		this.removeVisibilityListener();
		this.visibilityChangeHandler = () => {
			if (document.visibilityState === "visible") this.performHeartbeatCheck();
		};
		document.addEventListener("visibilitychange", this.visibilityChangeHandler);
	}
	/**
	* Remove page visibility listener
	* @internal
	*/
	removeVisibilityListener() {
		if (typeof window === "undefined" || typeof document === "undefined" || !this.visibilityChangeHandler) return;
		document.removeEventListener("visibilitychange", this.visibilityChangeHandler);
		this.visibilityChangeHandler = null;
	}
};
//#endregion
//#region performance/FrameRateMonitor.ts
/**
* Frame rate monitor with 2-second sliding window.
* Aligned with Android/iOS FrameRateMonitor.
*
* @example
* ```ts
* controller.frameRateMonitorEnabled = true
* controller.onFrameRateInfo = (info) => {
*   console.log('FPS:', info.fps, 'Jank:', info.jankRatioPercent)
* }
* ```
*/
var FrameRateMonitor = class {
	enabled = false;
	onFrameRateInfo = null;
	lwFrameCount = 0;
	lwStartTimeMs = 0;
	lwLastEndTimeMs = 0;
	lwJankCount = 0;
	lwSumInterval = 0;
	lwSumIntervalSq = 0;
	/** Per-frame GPU render time samples (ms) over the round; only >0 pushed. For percentiles. */
	lwGpuSamples = [];
	/** Reset the lightweight counter. Call at playback start. */
	resetPlaybackStats() {
		this.lwFrameCount = 0;
		this.lwStartTimeMs = performance.now();
		this.lwLastEndTimeMs = 0;
		this.lwJankCount = 0;
		this.lwSumInterval = 0;
		this.lwSumIntervalSq = 0;
		this.lwGpuSamples = [];
	}
	/** Get lightweight playback stats. Call at playback end. */
	getPlaybackStats() {
		const elapsed = performance.now() - this.lwStartTimeMs;
		const avgFps = elapsed > 0 ? this.lwFrameCount * 1e3 / elapsed : 0;
		const intervalCount = Math.max(0, this.lwFrameCount - 1);
		const jankRatio = intervalCount > 0 ? this.lwJankCount / intervalCount * 100 : 0;
		let fpsCv = 0;
		if (intervalCount > 0) {
			const mean = this.lwSumInterval / intervalCount;
			if (mean > 0) {
				const variance = this.lwSumIntervalSq / intervalCount - mean * mean;
				fpsCv = Math.sqrt(Math.max(0, variance)) / mean;
			}
		}
		return {
			avgFps,
			frameCount: this.lwFrameCount,
			durationMs: Math.round(elapsed),
			jankRatio,
			jankFrameCount: this.lwJankCount,
			fpsCv,
			gpuRenderP50Ms: this.percentileInterval(this.lwGpuSamples, 50),
			gpuRenderP90Ms: this.percentileInterval(this.lwGpuSamples, 90),
			gpuRenderP95Ms: this.percentileInterval(this.lwGpuSamples, 95)
		};
	}
	frames = [];
	/**
	* Record a new frame and trigger callback with aggregated metrics.
	* @param record Per-frame timing
	* @param presentationFps Current display FPS (from AvatarView.currentFPS)
	* @internal
	*/
	newFrame(record, presentationFps) {
		this.lwFrameCount++;
		if (this.lwLastEndTimeMs > 0) {
			const interval = record.endTimeMs - this.lwLastEndTimeMs;
			if (interval > 0) {
				this.lwSumInterval += interval;
				this.lwSumIntervalSq += interval * interval;
				if (interval > 50) this.lwJankCount++;
			}
		}
		this.lwLastEndTimeMs = record.endTimeMs;
		if (record.renderTimeMs > 0) this.lwGpuSamples.push(record.renderTimeMs);
		if (!this.enabled) return;
		const now = performance.now();
		this.frames = this.frames.filter((f) => now - f.endTimeMs <= 2e3);
		this.frames.push(record);
		const info = this.computeFrameRateInfo(presentationFps);
		this.onFrameRateInfo?.(info);
	}
	computeFrameRateInfo(presentationFps) {
		const frames = this.frames;
		if (frames.length === 0) return {
			fps: 0,
			presentationFps,
			frameIntervalP95Ms: 0,
			frameIntervalP99Ms: 0,
			jankRatioPercent: 0,
			averageFrameTimeMs: 0,
			cpuUsagePercent: 0,
			frames: []
		};
		const intervals = [];
		for (let i = 1; i < frames.length; i++) {
			const dt = frames[i].endTimeMs - frames[i - 1].endTimeMs;
			if (dt > 0) intervals.push(dt);
		}
		let fps = 0;
		if (frames.length >= 2) {
			const span = frames[frames.length - 1].endTimeMs - frames[0].startTimeMs;
			if (span > 0) fps = frames.length * 1e3 / span;
		}
		let totalFrameTime = 0;
		for (const f of frames) totalFrameTime += f.endTimeMs - f.startTimeMs;
		const averageFrameTimeMs = totalFrameTime / frames.length;
		let cpuUsagePercent = 0;
		if (frames.length >= 2) {
			const wallTime = frames[frames.length - 1].endTimeMs - frames[0].startTimeMs;
			if (wallTime > 0) cpuUsagePercent = totalFrameTime / wallTime * 100;
		}
		return {
			fps,
			presentationFps,
			frameIntervalP95Ms: this.percentileInterval(intervals, 95),
			frameIntervalP99Ms: this.percentileInterval(intervals, 99),
			jankRatioPercent: this.jankRatio(intervals, 50),
			averageFrameTimeMs,
			cpuUsagePercent,
			frames
		};
	}
	percentileInterval(intervals, percentile) {
		if (intervals.length === 0) return 0;
		const sorted = [...intervals].sort((a, b) => a - b);
		const rank = percentile / 100 * (sorted.length - 1);
		const lower = Math.floor(rank);
		const upper = Math.ceil(rank);
		if (lower === upper) return sorted[lower];
		const weight = rank - lower;
		return sorted[lower] + (sorted[upper] - sorted[lower]) * weight;
	}
	jankRatio(intervals, thresholdMs) {
		if (intervals.length === 0) return 0;
		let jankCount = 0;
		for (const interval of intervals) if (interval > thresholdMs) jankCount++;
		return 100 * jankCount / intervals.length;
	}
};
