		if (end) this.reqEnd = true;
		if (!this.isPlaying && this.currentState === AvatarState.idle) {
			this.currentState = AvatarState.active;
			this.notifyConversationState(AvatarState.active);
		}
		this.traceActions.sends.push({
			startTs: sendStartTs,
			endTs: monoTimestamp(),
			audioMs: sendAudioMs
		});
