		this.clearPlaybackData();
		if (this.networkLayer) this.networkLayer.disconnect();
		else this.currentConversationId = null;
		this.reqEnd = false;
		this.isConnected = false;
		this.onConnectionState?.(ConnectionState.disconnected);
