/**
* Splat depth sorting (Radix Sort optimized version)
* Uses 11-bit radix sort, O(n) time complexity
*/
var depthBuffer = null;
var depthInt = null;
var indices0 = null;
var indices1 = null;
var result = null;
var counts = null;
var BUCKET_SIZE = 2048;
var MASK = BUCKET_SIZE - 1;
/**
* Sort splats by depth (Radix Sort)
* @param packedData Packed format data [pos3, color4, cov6] x N
* @param cameraPosition Camera position
* @param cameraForward Camera forward vector
* @internal
*/
function sortSplats(packedData, cameraPosition, cameraForward) {
	const floatsPerPoint = 13;
	const splatCount = packedData.length / floatsPerPoint;
	if (!depthBuffer || depthBuffer.length !== splatCount) {
		depthBuffer = new Float32Array(splatCount);
		depthInt = new Uint32Array(depthBuffer.buffer);
		indices0 = new Uint32Array(splatCount);
		indices1 = new Uint32Array(splatCount);
		result = new Uint32Array(splatCount);
		counts = new Uint32Array(BUCKET_SIZE);
	}
	const depths = depthBuffer;
	const depthsInt = depthInt;
	const idx0 = indices0;
	const idx1 = indices1;
	const out = result;
	const cnt = counts;
	const cx = cameraPosition[0];
	const cy = cameraPosition[1];
	const cz = cameraPosition[2];
	const fx = cameraForward[0];
	const fy = cameraForward[1];
	const fz = cameraForward[2];
	for (let i = 0; i < splatCount; i++) {
		const offset = i * floatsPerPoint;
		depths[i] = (packedData[offset] - cx) * fx + (packedData[offset + 1] - cy) * fy + (packedData[offset + 2] - cz) * fz;
		idx0[i] = i;
	}
	for (let i = 0; i < splatCount; i++) {
		const d = depthsInt[i];
		depthsInt[i] = d ^ (-(d >> 31) | 2147483648);
	}
	radixPass(depthsInt, idx0, idx1, cnt, 0, splatCount);
	radixPass(depthsInt, idx1, idx0, cnt, 11, splatCount);
	radixPass(depthsInt, idx0, idx1, cnt, 22, splatCount);
	for (let i = 0; i < splatCount; i++) out[i] = idx1[splatCount - 1 - i];
	return out;
}
/**
* Single pass of radix sort
*/
function radixPass(keys, indicesIn, indicesOut, counts, shift, count) {
	counts.fill(0);
	for (let i = 0; i < count; i++) {
		const key = keys[indicesIn[i]] >> shift & MASK;
		counts[key]++;
	}
	let sum = 0;
	for (let i = 0; i < BUCKET_SIZE; i++) {
		const c = counts[i];
		counts[i] = sum;
		sum += c;
	}
	for (let i = 0; i < count; i++) {
		const idx = indicesIn[i];
		const key = keys[idx] >> shift & MASK;
		indicesOut[counts[key]++] = idx;
	}
}
