/**
* Packed Data utility functions
*
* Packed format: [pos3, color4, cov6] x N points
* Each point has 13 floats, 52 bytes total
*/
var FLOATS_PER_POINT = 13;
var reorderedBuffer = null;
/**
* Reorder packed data (reuse buffer)
* @param packedData Original data [pos3, color4, cov6] x N
* @param sortOrder Sort index array
* @returns Reordered data (reused buffer reference)
* @internal
*/
function reorderPackedData(packedData, sortOrder) {
	const pointCount = sortOrder.length;
	const requiredLength = pointCount * FLOATS_PER_POINT;
	if (!reorderedBuffer || reorderedBuffer.length !== requiredLength) reorderedBuffer = new Float32Array(requiredLength);
	for (let i = 0; i < pointCount; i++) {
		const srcOffset = sortOrder[i] * FLOATS_PER_POINT;
		const dstOffset = i * FLOATS_PER_POINT;
		reorderedBuffer.set(packedData.subarray(srcOffset, srcOffset + FLOATS_PER_POINT), dstOffset);
	}
	return reorderedBuffer;
}
